import os, json, glob
import numpy as np

def _load_json(p):
    with open(p, "r") as f:
        return json.load(f)

def _is_len32_array(x):
    try:
        a = np.asarray(x, dtype=np.float32)
        return a.ndim == 1 and a.shape[0] == 32 and np.all(np.isfinite(a))
    except Exception:
        return False

def _walk_arrays(obj, path=""):
    out = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            out += _walk_arrays(v, f"{path}.{k}" if path else str(k))
    elif isinstance(obj, (list, tuple)):
        if _is_len32_array(obj):
            out.append((path, np.asarray(obj, dtype=np.float32)))
        else:
            # walk nested lists of dicts
            for i, v in enumerate(obj):
                out += _walk_arrays(v, f"{path}[{i}]")
    return out

def _best_gamma_candidate(cands):
    # Score arrays: prefer key path with 'gamma', values in [0,1.5], mean in [0.3,1.0]
    best = None
    best_score = -1e9
    for path, arr in cands:
        score = 0.0
        lp = path.lower()
        if "gamma" in lp: score += 2.0
        if "g" in lp: score += 0.2
        vmin, vmax = float(np.min(arr)), float(np.max(arr))
        mean = float(np.mean(arr))
        if 0.0 <= vmin and vmax <= 1.5: score += 1.0
        if 0.3 <= mean <= 1.0: score += 0.5
        # prefer smoother profiles
        diffs = np.diff(arr)
        score -= 0.1 * float(np.mean(np.abs(diffs)))
        if score > best_score:
            best_score = score
            best = (path, arr)
    return best

def _extract_gamma_from_file(p):
    try:
        obj = _load_json(p)
    except Exception:
        return None, None
    cands = _walk_arrays(obj)
    if not cands:
        return None, None
    path, arr = _best_gamma_candidate(cands)
    return path, arr

def _extract_per_condition_from_file(p):
    # Expect a dict of conditions; for each condition, pick the best 32-length array (prefer 'mae' keys)
    try:
        obj = _load_json(p)
    except Exception:
        return {}
    if not isinstance(obj, dict):
        return {}
    out = {}
    for cond_key, cond_val in obj.items():
        if not isinstance(cond_val, (dict, list)):
            continue
        cands = _walk_arrays(cond_val, path=str(cond_key))
        if not cands:
            continue
        # score per-condition arrays: prefer paths containing both 'mae' and 'step'
        best = None
        best_score = -1e9
        for path, arr in cands:
            lp = path.lower()
            score = 0.0
            if "mae" in lp: score += 1.0
            if "step" in lp or "by_step" in lp: score += 0.5
            # MAE expected ~0.02–0.04
            mean = float(np.mean(arr))
            if 0.015 <= mean <= 0.05: score += 0.5
            if score > best_score:
                best_score = score
                best = (path, arr)
        if best is not None:
            out[cond_key] = best[1]
    return out

def _monotonicity_violation(x):
    d = np.diff(x)
    return float(np.sum(np.clip(-d, 0, None)))

def _slope_energy(x):
    d = np.diff(x)
    return float(np.mean(d**2))

def _align_conditions(dicts):
    keys = set()
    for d in dicts:
        keys |= set(d.keys())
    agg = {}
    for k in sorted(keys):
        vals = [d[k] for d in dicts if k in d]
        if vals:
            agg[k] = np.mean(np.stack(vals, 0), 0)
    return agg

def test():
    gamma_dir = "storage/ariadne/analyses/fourier_learn_gamma_export_v2"
    pc_dir = "storage/ariadne/analyses/fourier_learn_gamma_per_condition"
    out_path = "storage/ariadne/analyses/fourier_learn_gamma_consolidated_v2.json"

    g_files = sorted(glob.glob(os.path.join(gamma_dir, "*.json")))
    pc_files = sorted(glob.glob(os.path.join(pc_dir, "*.json")))

    gamma_list = []
    g_meta = []
    for p in g_files:
        path, arr = _extract_gamma_from_file(p)
        if arr is not None:
            gamma_list.append(arr)
            g_meta.append({"file": p, "path": path, "mean": float(np.mean(arr)), "min": float(np.min(arr)), "max": float(np.max(arr))})

    pc_list = []
    for p in pc_files:
        per = _extract_per_condition_from_file(p)
        if per:
            pc_list.append(per)

    result = {
        "ok": True,
        "n_gamma_files": len(g_files),
        "n_gamma_used": len(gamma_list),
        "n_pc_files": len(pc_files),
        "n_pc_used": len(pc_list),
        "gamma_files": g_meta,
    }

    if gamma_list:
        g_mat = np.stack(gamma_list, 0)
        g_mean = g_mat.mean(0)
        g_std = g_mat.std(0)
        result["gamma_mean"] = g_mean.tolist()
        result["gamma_std"] = g_std.tolist()
        result["gamma_stats"] = {
            "monotonicity_violation": _monotonicity_violation(g_mean),
            "slope_energy": _slope_energy(g_mean),
            "tail_mean_last4": float(np.mean(g_mean[-4:])),
            "peak": {"value": float(g_mean.max()), "t_index": int(np.argmax(g_mean))}
        }

    if pc_list:
        cond_agg = _align_conditions(pc_list)
        result["per_condition_keys"] = list(cond_agg.keys())
        if cond_agg and "gamma_mean" in result:
            step_mat = np.stack([v for v in cond_agg.values()], 0)
            step_diff = step_mat.mean(0)
            a = np.array(result["gamma_mean"]) - np.mean(result["gamma_mean"])
            b = step_diff - step_diff.mean()
            denom = float(np.linalg.norm(a) * np.linalg.norm(b) + 1e-12)
            result["corr_gamma_vs_step_difficulty"] = float(np.dot(a, b) / denom) if denom > 0 else None

    os.makedirs(os.path.dirname(out_path), exist_ok=True)
    with open(out_path, "w") as f:
        json.dump(result, f, indent=2)
    print("Consolidation v2 complete:", out_path)
    print("Used:", result["n_gamma_used"], "gamma,", result["n_pc_used"], "per-condition")
    return result
